import {useEffect} from "react";
import axios from "axios";
import useNotificationContext from "../hook/useNotificationContext.ts";
import type {ExtendedAxiosError} from "../model";
import {useNavigate} from "react-router";
import cookie from "../utils/cookie.ts";
import type {AuthResponse} from "../model/auth.ts";
import useProfile from "../hook/useProfile.ts";
import useAuthContext from "../hook/useAuthContext.ts";
import useCartContext from "../hook/useCartContext.ts";
import Config from "../config/config.ts";
import GoogleLogo from "../assets/images/google-logo.svg";

const ButtonSignInGoogle = () => {
    const notification = useNotificationContext();
    const navigate = useNavigate();
    const auth = useAuthContext();
    const cart = useCartContext();
    const {getProfile} = useProfile();

    function handleRedirectGoogle() {
        window.location.href = `${Config.BASE_URL}/api/1.0/auth/google`;
    }

    useEffect(() => {
        const urlParams = new URLSearchParams(window.location.search);
        const token_temp = urlParams.get('token_temp');
        const error = urlParams.get('error');

        if (error) {
            navigate('/login', {replace: true});
            notification.errorNotificationClient(decodeURIComponent(error));
            return;
        }

        const autoLogin = async () => {
            try {
                const response = await axios.post<AuthResponse>(`${Config.BASE_URL}/api/1.0/auth/google/login`, {
                    tokenTemp: token_temp
                }, {
                    headers: {},
                    withCredentials: true,
                });
                if (response && response.data.success) {
                    cookie.set("token", response.data.data.accessToken, 1);
                    const profile = await getProfile();
                    if (!profile) {
                        notification.errorNotificationClient("Failed to fetch profile after login");
                        return;
                    }
                    auth.setAuthData({
                        role: profile.role,
                        name: profile.fullName,
                        email: profile.email,
                        photo: profile.photo || '',
                    });

                    cart.setOrderFor(profile.fullName);

                    if (["admin", "barista"].includes(profile.role)) {
                        navigate("/dashboard", {replace: true});
                    } else {
                        navigate("/", {replace: true});
                    }
                } else {
                    notification.errorNotificationClient(response?.data.message || "Login failed");
                }
            } catch (error) {
                console.error("Auto login error:", error);
                if (axios.isAxiosError(error)) {
                    if ((error as ExtendedAxiosError).response?.status === 401) {
                        notification.errorNotificationClient("Unauthorized access. Please login again.");
                        navigate('/login', {replace: true});
                        return;
                    }
                    const responseError = (error as ExtendedAxiosError).response?.data || {message: "Auto login failed"};
                    notification.errorNotificationClient(responseError.message);
                } else {
                    notification.errorNotificationClient("An unexpected error occurred");
                }
            }
        };
        if (token_temp) {
            autoLogin();
        }
    }, []);

    return (
        <button
            type="button"
            onClick={handleRedirectGoogle}
            className={
                "flex items-center justify-center gap-2 w-full px-4 py-2 " +
                "border rounded-lg transition-colors duration-200 " +
                "border-gray-300 hover:bg-gray-100 active:bg-gray-200 text-gray-700 " +
                "dark:border-gray-700 dark:hover:bg-gray-800 dark:active:bg-gray-700 dark:text-gray-200"
            }
        >
            <img
                src={GoogleLogo}
                alt="Google Logo"
                className="w-5 h-5"
            />
            <span className="text-gray-700 dark:text-gray-200 font-medium">Sign in with Google</span>
        </button>
    );
};

export default ButtonSignInGoogle;

import DummyProfile from "../assets/images/dummyProfile.png";
import ButtonTabProfile from "./ButtonTabProfile.tsx";
import { useEffect, useRef, useState } from "react";

interface ProfileTab {
  dataTabProfileUser: {
    to?: string;
    icon: React.ReactNode;
    title: string;
    onClick?: () => void;
  }[];
  user: {
    name: string;
    role: string;
  };
}

const ProfileTab: React.FC<ProfileTab> = ({ dataTabProfileUser, user: { name, role } }) => {
  const [openTabProfile, setOpenTabProfile] = useState(false);
  const tabProfileRef = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      const tabProfileElement = tabProfileRef.current;
      if (openTabProfile && tabProfileElement && !tabProfileElement.contains(event.target as Node) && window.innerWidth < 640) {
        setOpenTabProfile(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  useEffect(() => {
    let fadeTimeOut: number;
    if (openTabProfile) {
      if (tabProfileRef.current) {
        tabProfileRef.current.classList.remove("hidden", "animate-fade-out");
        tabProfileRef.current.classList.add("animate-fade-in");
      }
    } else {
      if (tabProfileRef.current) {
        tabProfileRef.current.classList.remove("animate-fade-in");
        tabProfileRef.current.classList.add("animate-fade-out");
        fadeTimeOut = setTimeout(() => {
          if (tabProfileRef.current) {
            tabProfileRef.current.classList.add("hidden");
            tabProfileRef.current.classList.remove("animate-fade-out");
          }
        }, 300);
      }
    }
    return () => {
      if (fadeTimeOut) clearTimeout(fadeTimeOut);
    };
  }, [openTabProfile]);

  return (
    <div
      className="relative sm:w-40 dark:text-gray-100"
      onClick={(e) => {
        e.stopPropagation();
        setOpenTabProfile(!openTabProfile);
      }}
      onMouseEnter={() => setOpenTabProfile(true)}
      onMouseLeave={() => setOpenTabProfile(false)}
    >
      <div className="flex items-center gap-2 sm:gap-8">
        <div className="text-end hidden sm:block">
          <h4 className="font-bold sm:text-2xl dark:text-gray-100 leading-tight">{name}</h4>
          <p className="text-secondary text-xs sm:text-sm dark:text-gray-300">{role}</p>
        </div>
        <img src={DummyProfile} className="w-10 h-10 sm:w-14 sm:h-14 dark:brightness-90 rounded-full object-cover" alt="profile" />
      </div>
      <div
        ref={tabProfileRef}
        className="absolute right-0 mt-2 w-48 bg-white rounded-lg shadow-md transition-all duration-300 z-50 hidden dark:bg-gray-800 dark:shadow-none dark:border dark:border-gray-700 dark:text-gray-100"
      >
        {dataTabProfileUser.map((item, index) => (
          <ButtonTabProfile key={index} to={item.to} icon={item.icon} onClick={item.onClick} title={item.title} />
        ))}
      </div>
    </div>
  );
};

export default ProfileTab;

import ImgBgTopWallet from "../assets/images/bgTopWallet.png";
import Logo from "../assets/images/icon.png";
import {formatCurrency, formatNumberCurrency} from "../utils";
import ImgBgWalletNotActive from "../assets/images/ImgBgWalletNotActive.png";
import CardHistoryWallet from "./ui/card/CardHistoryWallet.tsx";
import Input from "./ui/form/Input.tsx";
import Modal from "./ui/Modal.tsx";
import {type FormEvent, useCallback, useEffect, useRef, useState} from "react";
import useNotificationContext from "../hook/useNotificationContext.ts";
import type {PayloadUpdateBalanceSSE, ResponseTopUp} from "../model/wallet.ts";
import useWallet from "../hook/useWallet.ts";
import CardHistoryWalletSkeleton from "./ui/Skeleton/CardHistoryWalletSkeleton.tsx";
import useSSE from "../hook/useSSE.ts";
import Config from "../config/config.ts";

interface WalletActiveProps {
    balance: number;
    setBalance: (value: React.SetStateAction<{
        balance: number;
        isActive: boolean;
    }>) => void;
    handleTopUp: (amount: number) => Promise<ResponseTopUp | null | undefined>;
}

const WalletActive: React.FC<WalletActiveProps> = ({balance, setBalance, handleTopUp}) => {
    const notification = useNotificationContext()
    const processedIds = useRef(new Set<string>());
    const refLoader = useRef<HTMLDivElement>(null);
    const {
        getHistoryBalance,
        loading,
        data,
        page,
        setData: setDataHistoryBalance,
        handlePaginate,
        totalData
    } = useWallet()
    const [loadingFirst, setLoadingFirst] = useState(true);
    const [showModal, setShowModal] = useState(false);
    const [amount, setAmount] = useState({
        amount: 0,
        amountFormatted: 'Rp 0',
    });
    const isMaxScroll = page * 10 >= totalData;
    useSSE<PayloadUpdateBalanceSSE>({
        baseUrl: `${Config.BASE_URL}/api/1.0/events?type=update_history_balance`,
        autoConnect: true,
        onMessage: useCallback((dataSSE) => {

            setDataHistoryBalance((prev) => {
                const dataExist = prev.find(item => item.id === dataSSE.balanceHistoryId);

                if (dataExist && dataSSE.status === 'COMPLETED' && !processedIds.current.has(dataSSE.balanceHistoryId)) {
                    processedIds.current.add(dataSSE.balanceHistoryId);
                    // ✅ Gunakan functional update agar tidak bergantung pada closure lama
                    setBalance(prevBalance => ({
                        balance: prevBalance.balance + dataExist.amount,
                        isActive: true
                    }));
                }


                return prev.map(item =>
                    item.id === dataSSE.balanceHistoryId
                        ? {...item, status: dataSSE.status.toLowerCase()}
                        : item
                );
            });
        }, [])
    })

    useEffect(() => {
        const fetchData = async () => {
            try {
                await getHistoryBalance();
            } finally {
                setLoadingFirst(false);
            }
        };
        fetchData();
    }, []);

    useEffect(() => {
        const target = refLoader.current;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !loading && !isMaxScroll) {
                    handlePaginate(page + 1);
                }
            }, {
                threshold: 1
            }
        )

        if (target && !loading && !isMaxScroll) {
            observer.observe(target);
        }

        return () => {
            if (target) {
                observer.unobserve(target);
            }
        }

    }, [page, loading]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const {name, value} = e.target;
        if (name === 'amount') {
            // Format price input to allow only numbers and commas
            const formattedValue = value.replace(/[^0-9,]/g, '').replace(/,/g, '.');
            setAmount({
                amount: parseFloat(formattedValue) || 0,
                amountFormatted: formatCurrency(parseFloat(formattedValue) || 0)
            })
            return;
        }
    }

    const handleSubmitTopUp = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (amount.amount <= 0) {
            notification.errorNotificationClient('Please enter a valid amount to top up.')
            return;
        }
        const res = await handleTopUp(amount.amount)
        if (res) {
            window.snap.pay(
                res.data.token,
                {
                    onError: (error) => {
                        console.error("Payment error:", error);
                        notification.errorNotificationClient('Payment failed, please try again.')
                        setShowModal(false)
                        handlePaginate(1)
                    },
                    onPending: (result) => {
                        notification.infoNotificationClient('Payment is pending, please continue to payment page.')
                        setShowModal(false)
                        handlePaginate(1)
                    },
                    onSuccess: (result) => {
                        notification.successNotificationClient('Top up successful!')
                        handlePaginate(1)
                        setShowModal(false);
                    },
                    onClose: () => {
                        notification.infoNotificationClient('Payment closed, please try again.')
                        setShowModal(false)
                        handlePaginate(1)
                    }
                }
            )
        }
    }

    const handleContinuePayment = async (token: string) => {
        window.snap.pay(
            token,
            {
                onError: (error) => {
                    console.error("Payment error:", error);
                    notification.errorNotificationClient('Payment failed, please try again.')
                    setShowModal(false)
                },
                onPending: (result) => {
                    notification.infoNotificationClient('Payment is pending, please continue to payment page.')
                    setShowModal(false)
                    handlePaginate(1)
                },
                onSuccess: (result) => {
                    notification.successNotificationClient('Top up successful!')
                    handlePaginate(1)
                    setShowModal(false);
                }
            }
        )
    }

    return (
        <>
            <Modal size={'md'} title={'Top Up Wallet'} show={showModal} handleClose={() => setShowModal(false)}>
                <div className="p-10">
                    <form onSubmit={handleSubmitTopUp}>
                        <Input type={'text'}
                               name={'amount'}
                               label={'Top Up Amount'}
                               placeholder={'Enter amount to top up'}
                               required={true}
                               onChange={handleChange}
                               value={amount.amountFormatted}
                        />
                        <div className="mt-10">
                            <button type="submit"
                                    className="w-full btn-primary text-white py-3 px-7 rounded-lg cursor-pointer">
                                Top Up
                            </button>
                        </div>
                    </form>
                </div>
            </Modal>
            <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl flex justify-between items-center'}>
                <h4 className={'font-bold text-5xl text-gray-900 dark:text-gray-100'}>
                    Wallet
                </h4>
            </div>
            <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl grid lg:grid-cols-2'}>
                <div className={'w-full mt-10'}>
                    <div className={'flex justify-between gap-5 sm:flex-row flex-col items-center w-full'}>
                        <h4 className={'font-bold text-2xl text-gray-900 dark:text-gray-100'}>
                            Your Balance
                        </h4>
                        <button onClick={() => setShowModal(true)}
                                className={'btn-primary px-8 py-2 rounded-md text-white'}>
                            Top Up
                        </button>
                    </div>
                    <div className={'w-full h-44 rounded-2xl rounded-b-none sm:h-48 bg-no-repeat bg-cover mt-20'}
                         style={
                             {
                                 backgroundImage: `url(${ImgBgTopWallet})`,
                             }
                         }>
                        <img className={'h-20 ms-7 pt-6'} src={Logo} alt={'Logo'}/>
                        <h5 className={'text-end text-2xl sm:text-5xl me-8 pt-4 font-thin text-white'}>Wallet</h5>
                    </div>
                    <div
                        className={'h-44 rounded-2xl rounded-t-none sm:h-48 w-full rounded-b-md py-8 px-7 space-y-6 bg-[#263238] dark:bg-gray-900'}>
                        <h4 className={'text-2xl sm:text-5xl text-white'}>
                            Rp.
                        </h4>
                        <h6 className={'text-2xl sm:text-5xl text-white'}>
                            {formatNumberCurrency(balance)}
                        </h6>
                    </div>
                </div>
                <img className={'m-auto lg:block hidden'} src={ImgBgWalletNotActive}
                     alt={'Image background wallet not active'}/>
            </div>
            <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl'}>
                <h4 className={'font-bold mb-10 text-5xl text-gray-900 dark:text-gray-100'}>
                    History
                </h4>
                <div className={'mt-6 w-full'}>
                    {
                        loadingFirst ? Array.from({length: 10}, (_, index) => (
                                <CardHistoryWalletSkeleton key={index}/>
                            ))
                            :
                            totalData === 0 ? (
                                <p className="text-gray-500 dark:text-gray-300 py-32 text-center">No history
                                    available.</p>
                            ) : (
                                data.map((item, index) => (
                                    <CardHistoryWallet handleContinuePayment={handleContinuePayment} {...item}
                                                       key={index}/>
                                ))
                            )
                    }
                    {
                        !isMaxScroll &&
                        <div ref={refLoader} className={'flex mt-10 flex-col justify-center items-center w-full'}
                        >
                            <div className="spinner mx-auto mb-4">
                            </div>
                            <p className="text-gray-700 dark:text-gray-300">Load More ...</p>
                        </div>
                    }
                </div>
            </div>
        </>
    )
}

export default WalletActive

import {
    type AuthResponse,
    type BodyLogin,
    type BodyRegister,
    ChangePasswordSchema,
    RegisterSchema
} from "../model/auth.ts";
import {useRef, useState} from "react";
import {fetchWithRetry, formatErrorZod, validate} from "../utils";
import {ZodError} from "zod";
import {useNavigate} from "react-router";
import useNotificationContext from "./useNotificationContext.ts";
import axios from "axios";
import type {BaseResponse, } from "../model";
import useProfile from "./useProfile.ts";
import useAuthContext from "./useAuthContext.ts";
import useCartContext from "./useCartContext.ts";
import cookie from "../utils/cookie.ts";
import {baseApi} from "../utils/axios.ts";

const useAuth = () => {
    const [error, setError] = useState<BodyRegister>({
        email: "",
        password: "",
        fullName: "",
        confirmPassword: "",
    });
    const navigate = useNavigate();
    const notification = useNotificationContext()
    const {getProfile} = useProfile();
    const loading = useRef(false);
    const auth = useAuthContext()
    const cart = useCartContext()

    const register = async (data: BodyRegister) => {
        if (loading.current) return; // Prevent multiple submissions
        loading.current = true; // Set loading state to true
        try {
            // Reset error state before validation
            setError({
                email: "",
                password: "",
                fullName: "",
                confirmPassword: "",
            });
            validate(data, RegisterSchema);
            const response = await fetchWithRetry<AuthResponse>({
                url: "/api/1.0/auth/register",
                method: "post",
                body: data,
                config: {
                    headers: {
                        "Content-Type": "application/json",
                    },
                },
            })
            if (response && response.data.success) {
                notification.successNotificationClient(response.data.message)
                navigate("/login")
            } else {
                notification.errorNotificationClient(response?.data.message || "Registration failed")
            }
        } catch (error) {
            console.error("Registration error:", error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    email: "",
                    password: "",
                    fullName: "",
                    confirmPassword: "",
                }

                const dataMapError = formatErrorZod<BodyRegister>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                throw error;
            } else if (axios.isAxiosError(error)) {
                if ((error as ).response && (error as ).response?.data.message.includes("data already exists")) {
                    notification.errorNotificationClient("Email already exists");
                } else {
                    const responseError = (error as ).response?.data || {message: "An error occurred"};
                    notification.errorNotificationClient(responseError.message);
                }
            } else {
                notification.errorNotificationClient("An unexpected error occurred");
            }
        } finally {
            loading.current = false; // Reset loading state
        }
    }

    const login = async (data: BodyLogin) => {
        if (loading.current) return; // Prevent multiple submissions
        loading.current = true; // Set loading state to true
        try {
            // Reset error state before validation
            setError({
                email: "",
                password: "",
                fullName: "",
                confirmPassword: "",
            });
            const response = await fetchWithRetry<AuthResponse>({
                url: "/api/1.0/auth/login",
                method: "post",
                body: data,
                config: {
                    withCredentials: true,
                },
            })
            if (response && response.data.success) {
                cookie.set(
                    "token",
                    response.data.data.accessToken, 1
                )
                const profile = await getProfile();
                if (!profile) {
                    notification.errorNotificationClient("Failed to fetch profile after login");
                    return;
                }
                auth.setAuthData({
                    role: profile.role,
                    name: profile.fullName,
                    email: profile.email,
                    photo: profile.photo || '',
                })

                cart.setOrderFor(profile.fullName)

                if (["admin", "barista"].includes(profile.role)) {
                    navigate("/dashboard");
                } else {
                    navigate("/");
                }
            } else {
                notification.errorNotificationClient(response?.data.message || "Login failed")
            }
        } catch (error) {
            console.error("Login error:", error);
            if (axios.isAxiosError(error)) {
                const responseError = (error as ).response?.data || {message: "An error occurred"};
                notification.errorNotificationClient(responseError.message);
            } else {
                notification.errorNotificationClient("An unexpected error occurred");
            }
        } finally {
            loading.current = false; // Reset loading state
        }
    }

    const forgetPassword = async (data: { email: string }) => {
        if (loading.current) return; // Prevent multiple submissions
        loading.current = true; // Set loading state to true
        try {
            const response = await fetchWithRetry<BaseResponse<null>>({
                url: "/api/1.0/auth/forgot-password",
                method: "post",
                body: data,
            })

            if (response && response.data.success) {
                notification.successNotificationClient(response.data.message)
                navigate("/login", {
                    replace: true,
                })
            } else {
                notification.errorNotificationClient(response?.data.message || "Request failed")
            }
        } catch (error) {
            console.error("Request error:", error);
            if (axios.isAxiosError(error)) {
                const responseError = (error as ).response?.data || {message: "An error occurred"};
                notification.errorNotificationClient(responseError.message);
            } else {
                notification.errorNotificationClient("An unexpected error occurred");
            }
        } finally {
            loading.current = false; // Reset loading state
        }
    }

    const changePassword = async (data: { token: string, password: string, confirmPassword: string }) => {
        if (loading.current) return; // Prevent multiple submissions
        loading.current = true; // Set loading state to true
        try {
            // Reset error state before validation
            setError({
                email: "",
                password: "",
                fullName: "",
                confirmPassword: "",
            })
            validate(data, ChangePasswordSchema);

            const response = await baseApi.post<BaseResponse<null>>(
                "/api/1.0/auth/change-password",
                data,
            )

            if (response && response.data.success) {
                notification.successNotificationClient(response.data.message)
                navigate("/login", {
                    replace: true,
                })
            } else {
                notification.errorNotificationClient(response?.data.message || "Request failed")
            }
        } catch (error) {
            console.error("Request error:", error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    email: "",
                    password: "",
                    fullName: "",
                    confirmPassword: "",
                }

                const dataMapError = formatErrorZod<{ email: string }>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                throw error;
            } else if (axios.isAxiosError(error)) {
                const responseError = (error as ).response?.data || {message: "An error occurred"};
                notification.errorNotificationClient(responseError.message);
            } else {
                notification.errorNotificationClient("An unexpected error occurred");
            }
        } finally {
            loading.current = false; // Reset loading state
        }
    }

    return {
        register,
        changePassword,
        error,
        forgetPassword,
        login,
    }
}

export default useAuth;

import {useState} from "react";
import useNotificationContext from "./useNotificationContext.ts";
import {fetchWithRetry, formatErrorZod, validate} from "../utils";
import axios from "axios";
import type {BaseResponse,  queryPaginate} from "../model";
import {type Barista, BaristaSchema, type BodyBarista, type ResponseGetBarista} from "../model/barista.ts";
import {ZodError} from "zod";

const useBarista = () => {
    const [data, setData] = useState<Barista[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [loadingProgress, setLoadingProgress] = useState<boolean>(false);
    const [error, setError] = useState({
        password: '',
        email: '',
        fullName: '',
    });
    const [totalData, setTotalData] = useState<number>(0);
    const notification = useNotificationContext()
    const [page, setPage] = useState<number>(1);

    const getBarista = async () => {
        setLoading(true);
        try {
            const url = '/api/1.0/barista/list-barista?page=1&size=10';
            const response = await fetchWithRetry<ResponseGetBarista>(
                {
                    url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                setData(response.data.data.data);
                setTotalData(response.data.data.totalData)
                return response.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch barista data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch barista data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const addBarista = async (data: BodyBarista) => {
        if (loadingProgress) return;
        setLoadingProgress(true);
        try {
            setError({
                password: '',
                email: '',
                fullName: '',
            });
            validate(data, BaristaSchema);
            const res = await fetchWithRetry<BaseResponse<null>>({
                url: '/api/1.0/barista/register-barista',
                method: 'post',
                body: data,
            })
            if (res && res.data.success) {
                notification.successNotificationDashboard('Succesfully Add New Barista.');
                return res.data;
            } else {
                notification.errorNotificationDashboard('Failed to add barista.');
                return null;
            }
        } catch (error) {
