                }
            )
            if (response && response.data.success) {
                return response.data.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch menu data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch menu data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const getMenuUncategorized = async () => {
        setLoading(true);
        try {
            const url = '/api/1.0/menus/uncategorized?page=1&size=10';
            const response = await fetchWithRetry<ResponseGetMenuPagination>(
                {
                    url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                setData(response.data.data.data);
                setTotalData(response.data.data.totalData)
                return response.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch menu data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch menu data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const getMenuByCategory = async (id: number) => {
        setLoading(true);
        try {
            const url = '/api/1.0/menus/by-category?id=' + id;
            const response = await fetchWithRetry<ResponseGetMenuByCategory>(
                {
                    url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                setData(response.data.data || []);
                return response.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch menu data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch menu data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const addMenu = async (menu: BodyMenu) => {
        if (loadingProgress) return
        setLoadingProgress(true);
        try {
            setError({
                name: '',
                description: '',
                price: '',
                photo: ''
            })

            validate(menu, MenuSchema)

            if (!menu.photo) {
                notification.errorNotificationDashboard('Menu photo is required.');
                setError({
                    photo: 'Menu photo is required.',
                    name: '',
                    description: '',
                    price: ''
                });
                return null;
            }
            const resUploadFoto = await uploadMenuPhoto(menu.photo as File);
            if (!resUploadFoto) {
                notification.errorNotificationDashboard('Failed to upload menu photo.');
                return null;
            }
            menu.photo = resUploadFoto.data.url; // Use the uploaded file path
            const responseAddMenu = await fetchWithRetry<BaseResponse<null>>(
                {
                    url: '/api/1.0/menus',
                    method: 'post',
                    body: menu,
                }
            )
            if (responseAddMenu && responseAddMenu.data.success) {
                notification.successNotificationDashboard('Successfully Add Menu');
                navigate('/dashboard/manage-catalog');
                return responseAddMenu.data;
            } else {
                notification.errorNotificationDashboard('Failed to add menu.');
                return null;
            }

        } catch (error) {
            console.error('Error adding menu:', error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    photo: '',
                    name: '',
                    description: '',
                    price: ''
                }

                const dataMapError = formatErrorZod<BodyMenu>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                return null;
            } else if (axios.isAxiosError(error)) {
                if (typeof menu.photo === 'string' && menu.photo.startsWith('https')) {
                    deleteMenuPhoto(menu.photo);
                }
                if (error.response && error.response.data) {
                    const errData = (error as ).response?.data || {message: 'Unknown error'};
                    notification.errorNotificationDashboard(errData.message || 'Failed to add menu.');
                } else {
                    notification.errorNotificationDashboard('Network error or server is down.');
                }
            } else {
                notification.errorNotificationDashboard('Failed to add menu. Please try again later.');
            }
        } finally {
            setLoadingProgress(false)
        }
    }

    const editMenu = async (menu: BodyMenu) => {
        if (loadingProgress) return
        setLoadingProgress(true);
        try {
            setError({
                name: '',
                description: '',
                price: '',
                photo: ''
            })

            validate(menu, MenuSchema)

            if (!menu.photo) {
                notification.errorNotificationDashboard('Menu photo is required.');
                setError({
                    photo: 'Menu photo is required.',
                    name: '',
                    description: '',
                    price: ''
                });
                return null;
            }

            if (menu.photo && menu.photo instanceof File) {
                const resUploadFoto = await uploadMenuPhoto(menu.photo as File);
                if (!resUploadFoto) {
                    notification.errorNotificationDashboard('Failed to upload menu photo.');
                    return null;
                }
                menu.photo = resUploadFoto.data.url; // Use the uploaded file path
            }
            const responseEditMenu = await fetchWithRetry<BaseResponse<null>>(
                {
                    url: '/api/1.0/menus',
                    method: 'put',
                    body: menu,
                }
            )
            if (responseEditMenu && responseEditMenu.data.success) {
                if (menu.photoBefore && menu.photoBefore.startsWith('https') && menu.photoBefore !== menu.photo) {
                    deleteMenuPhoto(menu.photoBefore);
                }
                notification.successNotificationDashboard('Successfully Edit Menu');
                navigate('/dashboard/manage-catalog');
                return responseEditMenu.data;
            } else {
                notification.errorNotificationDashboard('Failed to edit menu.');
                return null;
            }
        } catch (error) {
            console.error('Error editing menu:', error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    photo: '',
                    name: '',
                    description: '',
                    price: ''
                }

                const dataMapError = formatErrorZod<BodyMenu>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                return null;
            } else handleApiError(error, 'Failed to edit menu.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoadingProgress(false)
        }
    }

    const updateAvailableMenu = async (id: number, isAvailable: boolean) => {
        if (loadingProgress) return
        setLoadingProgress(true);
        try {

            const res = await fetchWithRetry<BaseResponse<null>>({
                url: '/api/1.0/menus/availability',
                body: {
                    id: id,
                    isAvailable: isAvailable
                },
                method: 'patch',
            })
            if (res && res.data.success) {
                notification.successNotificationDashboard(`Successfully update status`);
                return res.data;
            } else {
                notification.errorNotificationDashboard('Failed to update status.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to update status menu.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoadingProgress(false)
        }
    }

    const uploadMenuPhoto = async (file: File) => {
        try {
            const dataForm = new FormData();
            dataForm.append('file', file);
            const resUpload = await fetchWithRetry<ResponseUploadFoto>({
                url: "/api/1.0/upload/upload-menu",
                config: {
                    headers: {
                        "Content-Type": "multipart/form-data",
                    },
                },
                method: "post",
                body: dataForm,
            })
            if (resUpload && resUpload.data.success) {
                return resUpload.data;
            } else {
                notification.errorNotificationDashboard('Failed to upload menu photo.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to upload menu photo.', notification.errorNotificationDashboard);
        }
    }

    const deleteMenuPhoto = async (url: string) => {
        try {
            const resDelete = await fetchWithRetry<BaseResponse<null>>({
                url: `/api/1.0/upload/delete-menu?url=${encodeURIComponent(url)}`,
                method: "delete"
            })
            if (resDelete && resDelete.data.success) {
                return resDelete.data;
            } else {
                return null
            }
        } catch (error) {
            console.error('Error deleting menu photo:', error);
            return null
        }
    }

    const deleteMenu = async (id: number) => {
        if (loadingProgress) return
        setLoadingProgress(true);
        try {
            const response = await fetchWithRetry<BaseResponse<null>>(
                {
                    url: `/api/1.0/menus?id=${id}`,
                    method: 'delete',
                }
            )
            if (response && response.data.success) {
                notification.successNotificationDashboard('Successfully Delete Menu');
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to delete menu.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to delete menu.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoadingProgress(false);
        }
    }

    const handlePaginate = async (page: number, query: queryPaginate, urlParam?: string) => {
        if (loading) return;
        setLoading(true);
        try {
            let url = urlParam ? `${urlParam}?page=${page}&size=10` : `/api/1.0/menus?page=${page}&size=10`;

            let searchKey = '';
            let searchValue = '';
            if (query.search) {
                searchKey = 'name';
                searchValue = query.search;
            }
            if (query.category_id) {
                searchKey += (searchKey ? ',categoryId' : 'categoryId');
                searchValue += (searchValue ? `,${query.category_id}` : query.category_id);
            }
            if (searchKey && searchValue) {
                url += `&searchKey=${searchKey}&searchValue=${searchValue}`;
            }
            const response = await fetchWithRetry<ResponseGetMenuPagination>(
                {
                    url: url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                const token = Cookie.get('token');
                if (token) {
                    const role = jwtDecode<PayloadJWT>(token).role;
                    if (role === 'user') {
                        if (page === 1) {
                            setData(response.data.data.data);
                        } else {
                            const dataTemp = [
                                ...data,
                                ...response.data.data.data
                            ]
                            setData(dataTemp);
                        }
                    } else {
                        setData(response.data.data.data);
                    }
                } else {
                    if (page === 1) {
                        setData(response.data.data.data);
                    } else {
                        const dataTemp = [
                            ...data,
                            ...response.data.data.data
                        ]
                        setData(dataTemp);
                    }
                }
                setPage(page);
                setTotalData(response.data.data.totalData);
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to search menu data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch menu data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    return {
        data,
        loading,
        totalData,
        handlePaginate,
        deleteMenu,
        getMenu,
        addMenu,
        setLoading,
        page,
        getMenuUncategorized,
        editMenu,
        getMenuByCategory,
        error,
        getMenuById,
        updateAvailableMenu
    }
}

