                        setData([
                            ...data,
                            ...response.data.data.data
                        ])
                    } else {
                        setData(response.data.data.data);
                    }
                } else {
                    setData(response.data.data.data);
                }

                setTotalData(response.data.data.totalData);
                setPage(page);
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to search order data.');
