            }
        } catch (error) {
            handleApiError(error, 'Failed to checkout order.', notification.errorNotificationDashboard);
            return null
        } finally {
            setLoadingProgress(false);
        }
    }

    const handleSetRate = async (rating: number, id: number) => {
        if (loadingProgress) return null;
        setLoadingProgress(true);
        try {
            const data = {
                id: id,
                rating: rating
            }
            const res = await fetchWithRetry<BaseResponse<null>>({
                url: '/api/1.0/history-checkouts/set-rating-menu',
                method: 'patch',
                body: data,
            })
            if (res && res.data.success) {
                notification.successNotificationDashboard('Successfully rating menu.');
                return res.data;
            } else {
                notification.errorNotificationDashboard('Failed to rate menu.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to  rate menu.', notification.errorNotificationDashboard);
            return null
        } finally {
            setLoadingProgress(false);
        }
    }

    const getSummaryOrder = async (startDate: string, endDate: string) => {
        setLoading(true);
        try {
            const url = `/api/1.0/transactions/summary-report?startDate=${startDate}&endDate=${endDate}`;

            const response = await fetchWithRetry<ResponseGetSummaryReport>(
