import {fetchWithRetry} from "../utils";
import type {GetProfileResponse, UpdateProfile} from "../model/profile.ts";
import axios from "axios";
import useNotificationContext from "./useNotificationContext.ts";
import type {BaseResponse,  ResponseUploadFoto} from "../model";
import {useState} from "react";
import cookie from "../utils/cookie.ts";
import type {AuthResponse} from "../model/auth.ts";

const useProfile = () => {
    const notification = useNotificationContext()
    const [loadingProgress, setLoadingProgress] = useState<boolean>(false);

    const getProfile = async () => {
        try {
            const url = '/api/1.0/me';

            const res = await fetchWithRetry<GetProfileResponse>({
                url,
                method: 'get',
            })
            if (res && res.data.success) {
                return res.data.data
            } else {
                console.error('Failed to fetch profile:', res?.data.message || 'Unknown error');
                return null;
            }
        } catch (error) {
            console.error('Error fetching profile:', error);
            if (axios.isAxiosError(error)) {
                if (error.response && error.response.data) {
                    const errData = (error as ).response?.data || {message: 'Unknown error'};
                    if (errData.message.includes("Refresh token tidak ditemukan")) return
                    notification.errorNotificationClient(errData.message || 'Failed to fetch profile');
                } else {
                    notification.errorNotificationClient('Network error or server is down');
                }
            } else {
                notification.errorNotificationClient('An unexpected error occurred while fetching profile');
            }
            return null;
        }
    }

    const updateProfile = async (data: UpdateProfile) => {
        if (loadingProgress) return;
        setLoadingProgress(true);
        let isPhotoUploaded = false;
        try {
            if (data.photo instanceof File) {
                const uploadResult = await uploadProfilePhoto(data.photo);
                isPhotoUploaded = true;
                if (!uploadResult) {
                    notification.errorNotificationDashboard('Failed to upload profile photo.');
                    return null;
                }
                data.photo = uploadResult.data.url;
            } else if (data.preview.startsWith('https')) {
                data.photo = data.preview; // Use existing photo path if preview is a valid path
            }

            const url = '/api/1.0/update-profile';

            const res = await fetchWithRetry<AuthResponse>({
                url,
                method: 'patch',
                body: data,
                config: {
                    withCredentials: true
                }
            });

            if (res && res.data.success) {
                if (data.photoBefore && data.photoBefore !== data.photo) {
                    deleteProfilePhoto(data.photoBefore);
                }
                notification.successNotificationDashboard('Profile updated successfully.');
                cookie.set("token", res.data.data.accessToken, 1);
                return res.data.data;
            } else {
                notification.errorNotificationDashboard(res?.data.message || 'Failed to update profile.');
                return null;
            }

        } catch (error) {
            console.error('Error updating profile:', error);
            if (axios.isAxiosError(error)) {
                if (data.photo && typeof data.photo === 'string' && data.photo.startsWith('https') && isPhotoUploaded && data.photo !== data.preview) {
                    deleteProfilePhoto(data.photo) // Delete uploaded photo if profile update fails
                }
                if (error.response && error.response.data) {
                    const errData = (error as ).response?.data || {message: 'Unknown error'};
                    notification.errorNotificationDashboard(errData.message || 'Failed to update profile.');
                } else {
                    notification.errorNotificationDashboard('Network error or server is down.');
                }
            } else {
                notification.errorNotificationDashboard('Failed to add profile. Please try again later.');
            }
            return null
        } finally {
            setLoadingProgress(false);
        }
    }

    const uploadProfilePhoto = async (file: File) => {
        try {
            const dataForm = new FormData();
            dataForm.append('file', file);
            const resUpload = await fetchWithRetry<ResponseUploadFoto>({
                url: "/api/1.0/upload/upload-profile",
                config: {
                    headers: {
                        "Content-Type": "multipart/form-data",
                    },
                },
                method: "post",
                body: dataForm,
            })
            if (resUpload && resUpload.data.success) {
                return resUpload.data;
            } else {
                notification.errorNotificationDashboard('Failed to upload profile photo.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to upload profile photo.', notification.errorNotificationDashboard);
        }
    }

    const deleteProfilePhoto = async (url: string) => {
        try {
            const resDelete = await fetchWithRetry<BaseResponse<null>>({
                url: `/api/1.0/upload/delete-profile?url=${encodeURIComponent(url)}`,
                method: "delete"
            })
            if (resDelete && resDelete.data.success) {
                return resDelete.data;
            } else {
                return null
            }
        } catch (error) {
            console.error('Error deleting menu photo:', error);
            return null
        }
    }

    return {
        getProfile,
        updateProfile
    }
}

export default useProfile;

import cookie from "../utils/cookie.ts";
import {useCallback, useEffect, useRef} from "react";
import Jwt from "../utils/jwt.ts";
import apiClient, {refreshPromise, setRefreshPromise} from "../utils/axios.ts";
import type {RefreshTokenResponse} from "../model/auth.ts";

interface useSSEProps<T> {
    baseUrl: string;
    onMessage: (data: T) => void;
    autoConnect?: boolean;
    maxRetries?: number; // default unlimited (-1)
}

export default function useSSE<T>({
                                      baseUrl,
                                      onMessage,
                                      autoConnect = true,
                                      maxRetries = -1,
                                  }: useSSEProps<T>) {
    const eventSource = useRef<EventSource | null>(null);
    const retryCount = useRef(0);
    const retryTimeout = useRef<number | null>(null);

    const cleanUp = useCallback(() => {
        if (eventSource.current) {
            eventSource.current.close();
            eventSource.current = null;
        }
        if (retryTimeout.current) {
            clearTimeout(retryTimeout.current);
            retryTimeout.current = null;
        }
    }, []);

    const connect = useCallback(() => {
        if (eventSource.current) {
            console.warn("SSE is already connected.");
            return;
        }

        const token = cookie.get("token");
        if (!token) {
            console.error("No token found in cookies. Cannot connect to SSE.");
            return;
        }

        let url = `${baseUrl}`;
        url += url.includes("?") ? `&token=${token}` : `?token=${token}`;

        console.log("Connecting to SSE:", url);

        const es = new EventSource(url, {withCredentials: true});
        eventSource.current = es;

        es.onopen = () => {
            console.log("SSE connected");
            retryCount.current = 0; // reset kalau berhasil connect
        };

        es.onmessage = (event) => {
            try {
                const data: T = JSON.parse(event.data);
                onMessage(data);
            } catch (error) {
                console.error("Error parsing SSE message:", error);
            }
        };

        es.onerror = async () => {
            console.error("SSE connection error. Will retry...");
            es.close();
            eventSource.current = null;
            const token = cookie.get("token");
            if (!token) {
                console.error("No token found in cookies. Cannot reconnect to SSE.");
                return;
            }

            const expired = Jwt.isExpired(token);
            if (expired) {
                if (!refreshPromise) {
                    setRefreshPromise(apiClient.post<RefreshTokenResponse>("/api/1.0/auth/refresh", {}, {
                        withCredentials: true
                    }))
                }
                const res = await refreshPromise
                setRefreshPromise(null);
                if (res && res.data.success) {
                    cookie.set("token", res.data.data.accessToken, 1);
                } else {
                    cookie.erase("token");
                    window.location.href = "/login";
                    return;
                }
            }


            if (maxRetries === -1 || retryCount.current < maxRetries) {
                const delay = Math.min(1000 * 2 ** retryCount.current, 30000); // exponential backoff capped at 30s
                retryCount.current += 1;

                retryTimeout.current = setTimeout(() => {
                    console.log(`Retrying SSE connection (attempt ${retryCount.current})...`);
                    connect();
                }, delay);
            } else {
                console.error("Max retries reached. SSE will not reconnect.");
            }
        };
    }, [baseUrl, maxRetries]);

    useEffect(() => {
        if (autoConnect) {
            connect();
        }
        return () => {
            cleanUp();
        };
    }, [autoConnect, connect, cleanUp]);

    return {connect, disconnect: cleanUp};
}

import {useState} from "react";
import useNotificationContext from "./useNotificationContext.ts";
import {fetchWithRetry, formatErrorZod, validate} from "../utils";
import axios from "axios";
import type {BaseResponse,  queryPaginate} from "../model";
import {ZodError} from "zod";
import {
    type BodyTable,
    type ResponseGetTableNoPagination,
    type ResponseGetTablePagination,
    type Table,
    TableSchema
} from "../model/table.ts";

const useTable = () => {
    const [data, setData] = useState<Table[]>([]);
    const [options, setOptions] = useState<{ value: number; label: string }[]>([]);
    const [loading, setLoading] = useState<boolean>(false);
    const [loadingProgress, setLoadingProgress] = useState<boolean>(false);
    const [error, setError] = useState({
        name: '',
    });
    const [totalData, setTotalData] = useState<number>(0);
    const notification = useNotificationContext()
    const [page, setPage] = useState<number>(1);

    const getTable = async () => {
        setLoading(true);
        try {
            const url = '/api/1.0/tables?page=1&size=10';
            const response = await fetchWithRetry<ResponseGetTablePagination>(
                {
                    url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                setData(response.data.data.data);
                setTotalData(response.data.data.totalData)
                return response.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch table data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch table data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const getTableOptions = async () => {
        setLoading(true);
        try {
            const url = '/api/1.0/tables?noPaginate=true';
            const response = await fetchWithRetry<ResponseGetTableNoPagination>(
                {
                    url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                const data = response.data.data.map((table) => ({
                    value: table.id,
                    label: table.name
                }));
                setOptions(data);
                return response.data;
            } else {
                console.error(response);
                notification.errorNotificationDashboard('Failed to fetch table data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch table data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    const addTable = async (data: BodyTable) => {
        if (loadingProgress) return;
        setLoadingProgress(true);
        try {
            setError({
                name: ''
            });
            validate(data, TableSchema);
            const res = await fetchWithRetry<BaseResponse<null>>({
                url: '/api/1.0/tables',
                method: 'post',
                body: data,
            })
            if (res && res.data.success) {
                notification.successNotificationDashboard('Succesfully Add New Table.');
                return res.data;
            } else {
                notification.errorNotificationDashboard('Failed to add table.');
                return null;
            }
        } catch (error) {
            console.error('Error adding table:', error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    name: ''
                }

                const dataMapError = formatErrorZod<BodyTable>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                return null;
            } else handleApiError(error, 'Failed to add table.', notification.errorNotificationDashboard);
        } finally {
            setLoadingProgress(false);
        }
    }

    const updateTable = async (data: BodyTable & {
        id: number;
    }) => {
        if (loadingProgress) return;
        setLoadingProgress(true);
        try {
            setError({
                name: ''
            });
            validate(data, TableSchema);
            const res = await fetchWithRetry<BaseResponse<null>>({
                url: '/api/1.0/tables',
                method: 'put',
                body: data,
            })
            if (res && res.data.success) {
                notification.successNotificationDashboard('Succesfully Update Table.');
                return res.data;
            } else {
                notification.errorNotificationDashboard('Failed to update table.');
                return null;
            }
        } catch (error) {
            console.error('Error updating table:', error);
            if (error instanceof ZodError) {
                const defaultErrorMap = {
                    name: ''
                }

                const dataMapError = formatErrorZod<BodyTable>(error);

                Object.assign(defaultErrorMap, dataMapError);

                setError(defaultErrorMap);

                return null;
            } else handleApiError(error, 'Failed to update table.', notification.errorNotificationDashboard);
        } finally {
            setLoadingProgress(false);
        }
    }

    const deleteTable = async (id: number) => {
        if (loadingProgress) return
        setLoadingProgress(true);
        try {
            const response = await fetchWithRetry<BaseResponse<null>>(
                {
                    url: `/api/1.0/tables?id=${id}`,
                    method: 'delete',
                }
            )
            if (response && response.data.success) {
                notification.successNotificationDashboard('Successfully Delete Table.');
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to delete table.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to delete table.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoadingProgress(false);
        }
    }

    const handlePaginate = async (page: number, query: queryPaginate) => {
        if (loading) return;
        setLoading(true);
        try {
            const url = `/api/1.0/tables?page=${page}&size=10&searchValue=${query.search || ''}&searchKey=name`;
            const response = await fetchWithRetry<ResponseGetTablePagination>(
                {
                    url: url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                setData(response.data.data.data);
                setTotalData(response.data.data.totalData);
                setPage(page);
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to search table data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch table data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    return {
        data,
        loading,
        totalData,
        handlePaginate,
        getTable,
        setLoading,
        page,
        error,
        addTable,
        updateTable,
        deleteTable,
        getTableOptions,
        options,
        setOptions
    }
}

