    const handlePaginate = async (page: number,) => {
        if (loading) return;
        setLoading(true);
        try {
            const url = `/api/1.0/balance-history?page=${page}&size=10&sort=createdAt,desc`;
            const response = await fetchWithRetry<ResponseGetHistoryBalance>(
                {
                    url: url,
                    method: 'get',
                }
            )
            if (response && response.data.success) {
                if (page === 1) {
                    setData(response.data.data.data);
                } else {
                    const dataTemp = [
                        ...data,
                        ...response.data.data.data
                    ]
                    setData(dataTemp);
                }
                setPage(page);
                setTotalData(response.data.data.totalData);
                return response.data;
            } else {
                notification.errorNotificationDashboard('Failed to paginate history data.');
                return null;
            }
        } catch (error) {
            handleApiError(error, 'Failed to fetch history data.', notification.errorNotificationDashboard);
            return null;
        } finally {
            setLoading(false);
        }
    }

    return {
        checkWallet,
        loading,
        setPin,
        getHistoryBalance,
        data,
        totalData,
        handleTopUp,
        error,
        page,
        handlePaginate,
        setData
    }
}

