                setFormData({
                    ...formData,
                    photo: file
                });
            }
        }
    }

    const handleSelect = (value: { label: string; value: number } | null) => {
        setFormData({
            ...formData,
            category: value
        });
    }

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const data = {
            ...formData,
            categoryId: formData.category?.value,
        }
        addMenu(data)
    }

