            if (files && files[0]) {
                setFormData({
                    ...formData,
                    photo: files[0]
                });
            }
        } else if (e.target instanceof HTMLInputElement && e.target.files) {
            const file = e.target.files[0];
            if (file) {
                setFormData({
                    ...formData,
                    photo: file
                });
            }
        }
    }

    const handleSelect = (value: { label: string; value: number } | null) => {
