import CardListCategory from "../../../component/ui/card/CardListCategory.tsx";
import Input from "../../../component/ui/form/Input.tsx";
import Modal from "../../../component/ui/Modal.tsx";
import useCategory from "../../../hook/useCategory.ts";

const ListCategoryPage = () => {

    const [showModal, setShowModal] = useState(false);
    const [openTab, setOpenTab] = useState({
        add: false,
    });
    const [search, setSearch] = useState('');
    const [formData, setFormData] = useState({
        name: ''
    });
    const [selectedId, setSelectedId] = useState<number | null>(null);
    const {
        deleteCategory,
        data,
        addCategory,
        error,
        getCategory,
        page,
        totalData,
        handlePaginate,
        loading
    } = useCategory()
    const searcDebounce = useDebounce(handlePaginate, 1000);

    useEffect(() => {
        getCategory()
    }, [])

    const handleCloseModal = () => {
        setShowModal(false);
    }

    const showModalDelete = (id: number) => {
        setSelectedId(id);
        setShowModal(true);
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.name === 'search') {
            setSearch(e.target.value);
            searcDebounce(1, {search: e.target.value});
        } else {
            setFormData({
                ...formData,
                name: e.target.value
            });
        }
    }

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const res = await addCategory(formData)
        if (res) {
            setFormData({
                name: ''
            });
            setOpenTab({
                add: false,
            });
            handlePaginate(1, {search});
        } else {
            console.warn('Failed to add category');
        }
    }

    return (

        <Card variant="dashboard" className="mt-10">
            <Modal title={'Confirm Delete'} show={showModal} size={'sm'} handleClose={handleCloseModal}>
                <div className={'p-8'}>
                    <h4 className={'sm:text-2xl text-lg font-semibold text-center mb-4 text-slate-800 dark:text-slate-100'}>
                        Are you sure you want to remove
                        this category?
                    </h4>
                    <div className={'flex mt-14 justify-center gap-4'}>
                        <button onClick={
                            async () => {
                                if (!selectedId) return;
                                await deleteCategory(selectedId);
                                handleCloseModal();
                                handlePaginate(1, {search});
                            }
                        } className={'btn-primary text-white px-10 w-32 font-semibold py-2 rounded-lg'}>
                            Yes
                        </button>
                        <button className={'btn-danger text-white px-10 w-32 font-semibold py-2 rounded-lg'}
                                onClick={handleCloseModal}>
                            Cancel
                        </button>
                    </div>
                </div>
            </Modal>
            <div className={'flex sm:flex-row flex-col items-center gap-5 justify-between'}>
                <h4 className={'text-xl font-semibold text-slate-800 dark:text-slate-100'}>
                    Categories
                </h4>
                <div className={'gap-3 flex justify-center items-center'}>
                    <div>
                        <input value={search} name={'search'} onChange={handleChange} placeholder={'Search'}
                               className={'focus:ring-gray-300 border rounded-lg border-gray-300 dark:border-slate-600 placeholder-gray-400 dark:placeholder-gray-400 p-2 bg-white dark:bg-gray-700 text-slate-800 dark:text-slate-100'}/>
                    </div>
                    {
                        openTab.add ?
                            <button onClick={() => setOpenTab({
                                add: false,
                            })} className={'btn-danger text-white px-4 py-2 rounded-lg'}>
                                Close
                            </button>
                            :
                            <button onClick={() => setOpenTab({
                                add: true,
                            })} className={'btn-primary text-white px-4 py-2 rounded-lg'}>
                                Add
                            </button>
                    }
                </div>
            </div>
            <div
                className={`bg-[#FAFAFA] dark:bg-slate-700 overflow-hidden px-8 transition-all duration-500 ${openTab.add ? 'my-10 h-80' : 'h-0 '}`}>
                <div className={'border-b-2 pb-4 mt-4 border-b-[#E5E7EB] dark:border-b-slate-600'}>
                    <h4 className={'sm:text-xl text-sm text-slate-800 dark:text-slate-100'}>
