import Card from "../../../component/ui/Card.tsx";
import HeaderDashboard from "../../../component/HeaderDashboard.tsx";
import {Link, Outlet, useParams} from "react-router";
import CardListProductByCategory from "../../../component/ui/card/CardListProductByCategory.tsx";
import useMenu from "../../../hook/useMenu.ts";
import {useEffect, useState} from "react";
import Loading from "../../../component/ui/Loading.tsx";
import NotFoundPage from "../../404.tsx";

const ListProductByCategory = () => {
    const params = useParams<Readonly<{ id: string }>>()
    const [notFound, setNotFound] = useState(false);
    const [name, setName] = useState('');
    const {getMenuByCategory, data, loading} = useMenu();

    useEffect(() => {
        const fetchData = async () => {
            if (params.id) {
                const res = await getMenuByCategory(Number(params.id));
                if (res) {
                    setName(res.data[0].categoryName);
                } else {
                    setNotFound(true);
                }
            } else {
                setNotFound(true);
            }
        }
        fetchData();
    }, []);

    if (notFound) {
        return <NotFoundPage/>;
    }

    return (
        <div className={'container mx-auto px-4'}>
            <HeaderDashboard title={'Manage Categories'}
                             description={`you can organize and manage all categories available in your menu.`}/>
            <Card variant="dashboard" className="mt-10">
                <div className={'flex flex-col sm:flex-row items-center gap-4 justify-between'}>
                    <div className={'flex gap-20'}>
                        <h4 className={'text-xl font-semibold text-slate-800 dark:text-slate-100'}>
                            Category
                        </h4>
                        <h4 className={'text-xl text-slate-700 dark:text-slate-200'}>
                            {name}
                        </h4>
                    </div>
                    <div className={'gap-3 flex items-center'}>
                        <Link to={'/dashboard/manage-category/list-category'}
                              className={'btn-primary text-white px-4 py-2 rounded-lg dark:shadow-sm'}>
                            Back
                        </Link>
                    </div>
                </div>
                <div
                    className={'mt-10 grid xl:grid-cols-4 lg:grid-cols-3 md:grid-cols-2 sm:grid-cols-2 grid-cols-1 gap-6'}>
                    {
                        loading ?
                            <div className={'col-span-4'}>
                                <Loading/>
                            </div> :
                            data.length === 0 ?
                                <p className={'text-center text-2xl font-semibold col-span-4 text-slate-800 dark:text-slate-200'}>No
                                    data menu found</p> :
                                data.map((menu, index) => (
                                    <CardListProductByCategory key={index} name={menu.name}
                                                               description={menu.description}
                                                               image={`${menu.photo}`}/>
                                ))
                    }
                </div>
            </Card>
            <Outlet/>
        </div>
    );
}

