const ManageTablesPage = () => {

    const [showModal, setShowModal] = useState(false);
    const [openTab, setOpenTab] = useState({
        add: false,
        edit: false
    });
    const [search, setSearch] = useState('');
    const [formData, setFormData] = useState({
        name: '',
    });
    const [selectedId, setSelectedId] = useState<number | null>(null);
    const {
        getTable,
        data,
        deleteTable,
        page,
        error,
        updateTable,
        addTable,
        totalData,
        handlePaginate,
        loading
    } = useTable()


    const searchDebounce = useDebounce(handlePaginate, 1000);

    useEffect(() => {
        getTable()
    }, [])

    const handleCloseModal = () => {
        setShowModal(false);
    }

    const showModalDelete = (id: number) => {
        setSelectedId(id);
        setShowModal(true);
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.name === 'search') {
            setSearch(e.target.value);
            searchDebounce(1, {search: e.target.value});
        } else {
            setFormData({
                ...formData,
                [e.target.name]: e.target.value
            });
        }
    }

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (openTab.edit) {
            if (!selectedId) return;
            const dataTemp = {
                name: formData.name,
                id: selectedId
            }
            const res = await updateTable(dataTemp);
            if (res) {
                setOpenTab({add: false, edit: false});
                setFormData({
                    name: ''
                });
                handlePaginate(1, {search});
            }
            return;
        }
        const res = await addTable(formData);
        if (res) {
            setOpenTab({add: false, edit: false});
            setFormData({
                name: ''
            });
            handlePaginate(1, {search});
        }
    }

    const showTabUpdate = (id: number) => {
        const dataTemp = data.find(item => item.id === id);
        if (dataTemp) {
            setFormData({
                name: dataTemp.name
            });
            setSelectedId(id);
            setOpenTab({
                add: false,
                edit: true
