                                        add: false,
                                        edit: false
                                    })
                                }} className={'btn-danger text-white px-4 py-2 rounded-lg'}>
                                    Close
                                </button>
                                :
                                <button onClick={() => setOpenTab({
                                    add: true,
                                    edit: false
                                })} className={'btn-primary text-white px-4 py-2 rounded-lg dark:shadow-sm'}>
                                    Add
                                </button>
                        }
