    useEffect(
        () => {
            const fetchData = async () => {
                const res = await getOrderById(Number(params.id));
                if (res) {
                    setData(res.data);
                    setNotFound(false);
                } else {
                    setNotFound(true);
                }
            }

            fetchData();
