import {useEffect, useState} from "react";
import {Link} from "react-router";
import {FaPlus} from "react-icons/fa";
import InputIcon from "../../component/ui/form/InputIcon.tsx";
import {CiUser} from "react-icons/ci";
import DropDownIcon from "../../component/ui/form/DropDownIcon.tsx";
import CheckBox from "../../component/ui/form/CheckBox.tsx";
import {formatCurrency} from "../../utils";
import useCartContext from "../../hook/useCartContext.ts";
import CardCart from "../../component/ui/card/CardCart.tsx";
import useTable from "../../hook/useTable.ts";
import useNotificationContext from "../../hook/useNotificationContext.ts";
import Input from "../../component/ui/form/Input.tsx";
import Modal from "../../component/ui/Modal.tsx";
import useOrder from "../../hook/useOrder.ts";
import type {BodyOrder} from "../../model/order.ts";
import PageHeader from "../../component/PageHeader.tsx";
import Card from "../../component/ui/Card.tsx";

const CartPage = () => {

    const [formData, setFormData] = useState<{
        name: string;
        table: { value: number; label: string } | null;
        pin: string;
    }>({
        name: '',
        pin: '',
        table: {value: 0, label: ''}
    })
    const [selectedAll, setSelectedAll] = useState(false);
    const {getTableOptions, options, setOptions} = useTable()
    const notification = useNotificationContext()
    const [showModal, setShowModal] = useState(false);
    const [loadingCheckout, setLoadingCheckout] = useState(false);
    const cart = useCartContext()
    const {handleCheckout} = useOrder();
    const total = cart.datas.reduce((acc, item) => {
        if (item.checked) {
            return acc + (item.price * item.amount);
        }
        return acc;
    }, 0);

    useEffect(() => {
        let isAllSelected = false
        if (cart.datas.length > 0) {
            isAllSelected = cart.datas.every(item => item.checked);
        }
        setSelectedAll(isAllSelected);
    }, [cart.datas]);

    useEffect(() => {
        const fetchData = async () => {
            setFormData({
                name: cart.orderFor,
                pin: '',
                table: cart.tableId !== 0 ? {value: cart.tableId, label: cart.tableName} : null
            })
            const res = await getTableOptions()
            if (res && res.data.length > 0) {
                const dataFiltered = res.data.filter(item => item.id !== cart.tableId);
                setOptions(dataFiltered.map(item => ({
                    value: item.id,
                    label: item.name
                })));
            }
        }
        fetchData()
    }, []);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const {name, value} = e.target
        if (name === 'pin' && !/^\d*$/.test(value)) {
            return;
        }

        setFormData(prevState => ({
            ...prevState,
            [name]: value
        }));
        if (name === 'pin') return;
        cart.setOrderFor(value)
    };

    const handleChangeNotes = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
        const {value, name} = e.target;
        const id = parseInt(name.split('-')[1], 10);
        cart.setDatas(
            cart.datas.map(item => {
                if (item.id === id) {
                    return {...item, notes: value};
                }
                return item;
            })
        )
    };

    const handleChangeCheckBox = (e: React.ChangeEvent<HTMLInputElement>) => {
        const {checked, name} = e.target;
        const id = parseInt(name.split('-')[1], 10);
        const dataUpdate = cart.datas.map(item => {
            if (item.id === id) {
                return {...item, checked: checked};
            }
            return item;
        });
        cart.setDatas(
            dataUpdate
        );
        setSelectedAll(dataUpdate.every(item => item.checked));
    };

    const handleChangeAmount = (data: { increment: boolean; id: number }) => {
        const {increment, id} = data;
        const dataUpdate = cart.datas.map(item => {
            if (item.id === id) {
                const newAmount = increment ? item.amount + 1 : Math.max(1, item.amount - 1);
                return {...item, amount: newAmount};
            }
            return item;
        });
        cart.setDatas(
            dataUpdate
        );
    };

    const handleChangeTable = (value: { value: number; label: string } | null) => {
        setFormData(prevState => ({
            ...prevState,
            table: value
        }));
        cart.setTable({
            tableId: value ? value.value : 0,
            tableName: value ? value.label : ''
        })
    };

    const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
        const isChecked = e.target.checked;
        setSelectedAll(isChecked);
        const dataUpdate = cart.datas.map(item => ({
            ...item,
            checked: isChecked
        }));
        cart.setDatas(
            dataUpdate
        )
    };

    const handleShowModalCheckout = () => {
        if (!formData.name) {
            notification.errorNotificationClient('Please enter a name for the order')
            return;
        }
        if (!formData.table || !formData.table.value) {
            notification.errorNotificationClient('Please select a table')
            return;
        }
        setFormData({
            ...formData,
            pin: ''
        })
        const selectedItems = cart.datas.filter(item => item.checked);
        if (selectedItems.length === 0) {
            notification.errorNotificationClient('Please select at least one item to checkout')
            return;
        }
        setShowModal(true)
    }

    const handleSubmitCheckout = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (formData.pin === '' || !formData.table || formData.table.value === 0) {
            return;
        }
        if (formData.pin.length != 6) {
            notification.errorNotificationClient('Pin must be 6 digits')
            return;
        }
        setLoadingCheckout(true);
        const payload: BodyOrder = {
            pin: formData.pin,
            orderFor: formData.name,
            tableId: formData.table.value,
            datas: cart.datas.filter(item => item.checked).map(item => ({
                menuId: item.id,
                qty: item.amount,
                notes: item.notes
            }))
        }
        const res = await handleCheckout(payload)
        if (res) {
            cart.setCart({
                tableId: 0,
                tableName: '',
                orderFor: cart.orderFor,
                datas: cart.datas.filter(item => !item.checked),
            })
            setFormData({
                name: cart.orderFor,
                pin: '',
                table: {value: 0, label: ''}
            })
            setShowModal(false);
        }
        setLoadingCheckout(false);
    };

    return (
        <section className="container mx-auto my-10 px-4 text-gray-900 dark:text-gray-100">
            <Modal size={'md'} title={'Checkout'} show={showModal} handleClose={() => setShowModal(false)}>
                <div className="p-10 bg-white dark:bg-gray-800 rounded-lg">
                    <form onSubmit={handleSubmitCheckout}>
                        <Input type={'password'}
                               name={'pin'}
                               label={'Pin'}
                               placeholder={'Enter your pin'}
                               required={true}
                               onChange={handleChange}
                               value={formData.pin}
                        />
                        <div className="mt-10">
                            <button type="submit" disabled={loadingCheckout}
                                    className={`w-full btn-primary text-white py-3 px-7 rounded-lg font-bold ${loadingCheckout ? 'btn-loading' : ''}`}>
                                {loadingCheckout ? 'Processing...' : 'Checkout'}
                            </button>
                        </div>
                    </form>
                </div>
            </Modal>

            <PageHeader
                breadcrumb={[{label: 'Menu', to: '/menu'}, {label: 'Cart'}]}
                title="Cart"
            />

            <Card variant="default" padding="lg" className="mb-6">
                <div className="flex justify-between gap-5 sm:flex-row flex-col items-center">
                    <h4 className="font-bold text-3xl text-gray-900 dark:text-gray-100">
                        Diskusi Coffee
                    </h4>
                    <Link to={'/menu'}
                          className="text-primary font-bold text-base flex items-center gap-2">
                        <FaPlus/>
                        Add Menu
                    </Link>
                </div>
                <div className="flex justify-between mt-5 gap-5 md:flex-row flex-col items-center">
                    <div className="sm:w-96 w-full">
                        <InputIcon icon={<CiUser/>} onChange={handleChange} error={''} value={formData.name}
                                   type={'text'} name={'name'} placeholder={'Name'} label={'Order For'}
                                   required={true}/>
                    </div>
                    <div className="sm:w-96 w-full">
                        <DropDownIcon placeholder={'Select Table'} label={'Table'}
                                      options={options} icon={<CiUser/>}
                                      name={'table'}
                                      value={formData.table}
                                      setValue={handleChangeTable}
                                      setOptions={setOptions}/>
                    </div>
                </div>
            </Card>

            {cart.datas.length === 0 ? (
                <Card variant="default" padding="lg" className="text-center">
                    <div className="flex flex-col justify-center items-center py-16">
                        <h3 className="text-2xl font-bold mb-4 text-gray-900 dark:text-gray-100">
                            Your cart is empty
                        </h3>
                        <p className="text-gray-500 dark:text-gray-400 max-w-md">
                            Looks like you haven't added anything yet.
                            Browse our menu to find your favorite coffee!
                        </p>
                        <Link to={'/menu'}
                              className="btn-primary text-white px-8 py-3 rounded-2xl mt-8 font-bold">
                            Browse Menu
                        </Link>
                    </div>
                </Card>
            ) : (
                <Card variant="default" padding="lg">
                    <div className="my-6">
                        <CheckBox name={"select all"} value={selectedAll} onChange={handleSelectAll}
                                  label={'Select All'}/>
                    </div>
                    <div className="grid sm:grid-cols-2 xl:grid-cols-3 my-10 gap-10">
                        {cart.datas.map((item, index) => (
                            <CardCart handleChangeNotes={handleChangeNotes}
                                      handleChangeCheckBox={handleChangeCheckBox}
                                      handleChangeAmount={handleChangeAmount} {...item}
                                      photo={`${item.photo}`}
                                      key={index}/>
                        ))}
                    </div>
                    <div className="flex mt-10 justify-end">
                        <button
                            onClick={handleShowModalCheckout}
                            className="btn-tertiary flex items-center justify-between px-8 font-bold py-3 w-full max-w-lg rounded-2xl">
                            Checkout
                            <span>{formatCurrency(total)}</span>
                        </button>
                    </div>
                </Card>
            )}
        </section>
    );
}

export default CartPage;

import DummyProduct from "../../assets/images/dummyProduct.png";
import {formatCurrency} from "../../utils";
import CardMenu from "../../component/ui/card/CardMenu.tsx";
import useMenu from "../../hook/useMenu.ts";
import {useEffect, useState} from "react";
import {useNavigate, useParams} from "react-router";
import NotFoundPage from "../404.tsx";
import type {Menu, ResponseGetMenuPagination} from "../../model/menu.ts";
import DetailMenuSkeleton from "../../component/ui/Skeleton/DetailMenuSkeleton.tsx";
import CardMenuSkeleton from "../../component/ui/Skeleton/CardMenuSkeleton.tsx";
import useAuthContext from "../../hook/useAuthContext.ts";
import RatingDetailMenu from "../../component/RatingDetailMenu.tsx";
import {CiCircleMinus, CiCirclePlus} from "react-icons/ci";
import useNotificationContext from "../../hook/useNotificationContext.ts";
import useCartContext from "../../hook/useCartContext.ts";

const DetailMenu = () => {

    const {getMenuById, handlePaginate} = useMenu()
    const params = useParams<Readonly<{ id: string }>>()
    const [loading, setLoading] = useState(true);
    const [form, setForm] = useState({
        notes: '',
        amount: 1,
    });
    const auth = useAuthContext()
    const notification = useNotificationContext()
    const cart = useCartContext()
    const [notFound, setNotFound] = useState(false)
    const [showDescription, setShowDescription] = useState(true);
    const navigate = useNavigate()
    const [data, setData] = useState<Menu>({
        rating: 0,
        id: 0,
        name: '',
        price: 0,
        photo: '',
        categoryId: 0,
        description: '',
        isAvailable: true,
        categoryName: '',
    });
    const [dataSuggest, setDataSuggest] = useState<Menu[]>([]);

    useEffect(
        () => {
            const fetchData = async () => {
                try {
                    const resDetail = await getMenuById(Number(params.id))
                    if (!resDetail) {
                        setNotFound(true);
                    } else {
                        setNotFound(false);
                        setData(resDetail);
                        const resDataSuggest = await handlePaginate(1, {
                            category_id: resDetail.categoryId,
                            search: '',
                        });
                        const dataSuggest = resDataSuggest as ResponseGetMenuPagination;
                        if (resDataSuggest && Array.isArray(dataSuggest.data)) {
                            const dataSuggestTemp = (dataSuggest.data).filter(item => item.id !== Number(params.id));
                            setDataSuggest(dataSuggestTemp);
                        } else {
                            setDataSuggest([]);
                        }
                    }
                } finally {
                    setLoading(false);
                    setShowDescription(true);
                    const cartData = cart.datas.find(item => item.id === Number(params.id));
                    if (cartData) {
                        setForm({
                            notes: cartData.notes || '',
                            amount: cartData.amount || 1,
                        });
                    } else {
                        setForm({
                            notes: '',
                            amount: 1,
                        });
                    }
                }
            };
            fetchData();
        }, [params.id]
    )

    const handleAddToCart = () => {
        if (!auth.isAuth) {
            notification.errorNotificationClient('You must login to add items to the cart');
            return navigate('/login');
        }
        const isAlreadyInCart = cart.datas.some(item => item.id === data.id);
        if (isAlreadyInCart) {
            const updatedCart = cart.datas.map(item => {
                if (item.id === data.id) {
                    return {
                        ...item,
                        amount: form.amount,
                        notes: form.notes,
                    };
                }
                return item;
            });
            cart.setDatas(
                updatedCart
            );
            notification.successNotificationClient(`Successfully update item in cart`)
        } else {
            const newData = [
                ...cart.datas,
                {
                    amount: form.amount,
                    id: data.id,
                    nameProduct: data.name,
                    price: data.price,
                    photo: data.photo,
                    checked: true,
                    notes: form.notes,
                }
            ]
            cart.setDatas(
                newData
            )
            notification.successNotificationClient(`Successfully add to cart`)
        }
    }

    if (auth.loading) {
        return null
    }

    if (notFound || (!data && !loading)) {
        return <NotFoundPage/>
    }

    return (
        <section className="container mx-auto my-10 px-4">
            <div className={'flex gap-5'}>
                <h4 className={'text-gray-900 dark:text-gray-100'}>
                    Menu
                </h4>
                <span className={'text-gray-600 dark:text-gray-400'}>
                    /
                </span>
                <h4 className={'font-bold text-gray-900 dark:text-gray-100'}>
                    Details
                </h4>
            </div>
            {
                loading ?
                    <DetailMenuSkeleton/> :
                    <>
                        <div
                            className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl flex sm:flex-row flex-col gap-5 justify-between items-center'}>
                            <h4 className={'font-bold text-3xl text-gray-900 dark:text-gray-100'}>
                                {
                                    data.name
                                }
                            </h4>
                            <div className={'flex items-center text-2xl'}>
                                <RatingDetailMenu rating={data.rating}/>
                                <h5 className={'ms-4 text-xl text-gray-900 dark:text-gray-100'}>
                                    ({data.rating})
                                </h5>
                            </div>
                        </div>
                        <div className={'flex md:flex-row flex-col gap-5'}>
                            <div
                                className={'mt-10 shrink-0 md:w-96 w-full mx-auto bg-white dark:bg-gray-800 p-8 rounded-2xl flex justify-between items-center'}>
                                <img src={data.photo}
                                     className={'w-96 mx-auto rounded-2xl h-96 object-cover'}
                                     alt={data.name}/>
                            </div>
                            <div
                                className={'mt-10 flex grow flex-col gap-10 bg-white dark:bg-gray-800 p-8 rounded-2xl'}>
                                <h3 className={'text-2xl font-bold text-gray-900 dark:text-gray-100'}>
                                    {data.name}
                                </h3>
                                <div className={'flex items-center gap-2 text-xl'}>
                                    <h5 className={'font-bold text-gray-900 dark:text-gray-100 text-xl'}>
                                        {formatCurrency(data.price)}
                                    </h5>
                                    |
                                    <p className={'text-gray-400 dark:text-gray-300'}>
                                        {
                                            data.isAvailable ? 'Stock tersedia' : 'Stock tidak tersedia'
                                        }
                                    </p>
                                </div>
                                {
                                    showDescription ?
                                        <p className={'text-gray-600 dark:text-gray-300'}>
                                            {
                                                data.description
                                            }
                                        </p>
                                        : <>
                                            <div className={'mt-5'}>
                                                <label className={'text-gray-600 dark:text-gray-300'}
                                                       htmlFor={'notes'}>
                                                    Notes
                                                    <textarea
                                                        className={'w-full h-32 p-4 border border-gray-300 dark:border-gray-700 rounded-lg mt-3 bg-white dark:bg-gray-700 text-gray-900 dark:text-gray-100'}
                                                        placeholder={'Add your notes here...'}
                                                        value={form.notes}
                                                        id={"notes"}
                                                        onChange={(e) => setForm({
                                                            ...form,
                                                            notes: e.target.value
                                                        })}
                                                    />
                                                </label>
                                            </div>
                                            <div className={'mt-5 flex items-center justify-between'}>
                                                <h5 className={'text-gray-900 dark:text-gray-100'}>
                                                    Amount
                                                </h5>
                                                <div className={'flex  items-center gap-2 text-xl'}>
                                                    <button
                                                        className={'disabled:cursor-not-allowed cursor-pointer text-gray-900 dark:text-gray-100'}
                                                        disabled={form.amount <= 1}
                                                        onClick={() => setForm({
                                                            ...form,
                                                            amount: form.amount > 1 ? form.amount - 1 : 1
                                                        })}>

                                                        <CiCircleMinus
                                                        />
                                                    </button>
                                                    <span className={'text-gray-600 dark:text-gray-300'}>
                                                        {form.amount}
                                                    </span>
                                                    <button
                                                        className={'cursor-pointer text-gray-900 dark:text-gray-100'}
                                                        onClick={() => setForm({
                                                            ...form,
                                                            amount: form.amount + 1
                                                        })}
                                                    >

                                                        <CiCirclePlus
                                                        />
                                                    </button>
                                                </div>
                                            </div>
                                            <div
                                                className={'text-gray-600 dark:text-gray-300 my-5 flex items-center justify-between'}>
                                                <h5 className={'text-gray-900 dark:text-gray-100'}>
                                                    Total
                                                </h5>
                                                <h5 className={'font-bold text-xl text-gray-900 dark:text-gray-100'}>
                                                    {formatCurrency(data.price * form.amount)}
                                                </h5>
                                            </div>
                                        </>
                                }
                                <div className={`mt-auto ms-auto ${!showDescription && 'w-full'}`}>
                                    {
                                        data.isAvailable ?
                                            <button onClick={() => {
                                                if (!auth.isAuth) {
                                                    return navigate('/login',)
                                                } else if (auth.isAuth) {
                                                    setShowDescription(!showDescription);
                                                    if (!showDescription) {
                                                        handleAddToCart()
                                                    }
                                                }
                                            }}
                                                    className={`btn-tertiary px-6 font-bold py-3 block  rounded-2xl  ${!showDescription && 'w-full'} text-black`}>
                                                Add to Cart
                                            </button>
                                            : null
                                    }
                                </div>
                            </div>
                        </div>
                    </>
            }
            <div className={'mt-10 '}>
                <h3 className={'text-xl font-bold text-gray-900 dark:text-gray-100'}>Suggested for You</h3>
            </div>
            <div className={'grid 2xl:grid-cols-6 sm:grid-cols-3 grid-cols-2 gap-10 mt-10 mb-20'}>
                {
                    loading ?
                        Array.from({length: 6}, (_, index) => (
                            <CardMenuSkeleton
                                key={index}
                            />
                        )) :
                        dataSuggest.length > 0 ? dataSuggest.slice(0, 6).map((menu, index) => (
                            <CardMenu
                                key={index}
                                id={menu.id}
                                photo={`${menu.photo || DummyProduct}`}
                                name={menu.name}
                                rating={menu.rating}
                            />
                        )) : (
                            <div className="col-span-6 text-center">
                                <p className="text-gray-500 dark:text-gray-400">No suggestions available</p>
                            </div>
                        )
                }
            </div>
        </section>
    );
}

export default DetailMenu;

import {useEffect, useState} from "react";
import useOrder from "../../hook/useOrder.ts";
import type {Order} from "../../model/order.ts";
import {useParams} from "react-router";
import NotFoundPage from "../404.tsx";
import {formatCurrency, formatDateTimeShortString} from "../../utils";
import CardMenuTransactionDetail from "../../component/ui/card/CardMenuTransactionDetail.tsx";
import DetailTransactionSkeleton from "../../component/ui/Skeleton/DetailTransactionSkeleton.tsx";

const DetailTransactionPage = () => {

    const {getOrderById, loading, handleSetRate} = useOrder();
    const [data, setData] = useState<Order>({
        id: 0,
        orderFor: '',
        tableName: '',
        orderBy: '',
        totalPrice: 0,
        details: [],
        orderStatus: 0,
        tableId: 0,
        userId: 0,
        createdAt: ''
    });
    const params = useParams<Readonly<{ id: string }>>()
    const [notFound, setNotFound] = useState(false);

    useEffect(() => {
        const fetchData = async () => {

            const res = await getOrderById(Number(params.id))
            if (res) {
                setData(res.data);
            } else {
                setNotFound(true);
            }

        }
        fetchData()
    }, []);

    if (notFound && !loading) {
        return <NotFoundPage/>
    }

    const handleSetRating = async (rating: number, id: number) => {
        const res = await handleSetRate(rating, id);
        if (res) {
            const updatedDetails = data.details.map((item) =>
                item.id === id ? {...item, rating} : item
            );
            setData((prevData) => ({
                ...prevData,
                details: updatedDetails,
            }));
        }
    }

    const statusLabel = [
        'Order Confirmed',
        'Delivering Order',
        'Order Completed'
    ]

    const statusClass = data.orderStatus === 1
        ? `text-[#F9A825] dark:text-[#F9A825]`
        : data.orderStatus === 3
            ? `text-[#47DC53] dark:text-[#47DC53]`
            : data.orderStatus === 2
                ? `text-[#DDE232] dark:text-[#DDE232]`
                : `text-gray-900 dark:text-gray-100`;

    return (
        <section className="container mx-auto my-10 px-4">
            <div className={'flex gap-5'}>
                <h4 className={'text-gray-900 dark:text-gray-100'}>
                    Menu
                </h4>
                <span className={'text-gray-600 dark:text-gray-400'}>
                    /
                </span>
                <h4 className={'text-gray-900 dark:text-gray-100'}>
                    Transactions
                </h4>
                <span className={'text-gray-600 dark:text-gray-400'}>
                    /
                </span>
                <h4 className={'font-bold text-gray-900 dark:text-gray-100'}>
                    Detail Orders
                </h4>
            </div>
            <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl flex justify-between items-center'}>
                <h4 className={'font-bold text-3xl sm:text-5xl text-gray-900 dark:text-gray-100'}>
                    Transactions
                </h4>
            </div>
            {

                loading ? <DetailTransactionSkeleton/> :
                    <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl '}>
                        <h4 className={'font-bold text-3xl text-gray-900 dark:text-gray-100'}>
                            Detail Orders
                        </h4>
                        <div className={'flex mb-10 md:flex-row flex-col gap-5 justify-between items-start mt-7'}>
                            <div className={'space-y-4'}>
                                <div className={'text-sm sm:text-xl flex items-start'}>
                                    <h5 className={'min-w-28 text-gray-700 dark:text-gray-300'}>
                                        Order For
                                    </h5>
                                    <span className={'text-gray-600 dark:text-gray-400'}>
                            &nbsp;:&nbsp;
                        </span>
                                    <p className={'text-gray-900 dark:text-gray-100'}>
                                        {data.orderFor}
                                    </p>
                                </div>
                                <div className={'text-sm sm:text-xl flex items-start'}>
                                    <h5 className={'min-w-28 text-gray-700 dark:text-gray-300'}>
                                        Order Table
                                    </h5>
                                    <span className={'text-gray-600 dark:text-gray-400'}>
                            &nbsp;:&nbsp;
                        </span>
                                    <p className={'text-gray-900 dark:text-gray-100'}>
                                        {data.tableName}
                                    </p>
                                </div>
                                <div className={'text-sm sm:text-xl flex items-start'}>
                                    <h5 className={'min-w-28 text-gray-700 dark:text-gray-300'}>
                                        Order Date
                                    </h5>
                                    <span className={'text-gray-600 dark:text-gray-400'}>
                            &nbsp;:&nbsp;
                        </span>
                                    <p className={'text-gray-900 dark:text-gray-100'}>
                                        {formatDateTimeShortString(data.createdAt)}
                                    </p>
                                </div>
                            </div>
                            <h5 className={`text-sm sm:text-xl font-bold ${statusClass} mt-0`}>
                                {
                                    statusLabel[data.orderStatus]
                                }
                            </h5>
                        </div>
                        <div className={'space-y-10'}>
                            {
                                data.details.length > 0 &&
                                data.details.map((item, index) => (
                                    <CardMenuTransactionDetail handleSetRate={handleSetRating} {...item} key={index}/>
                                ))
                            }
                        </div>
                        <div
                            className={'flex font-bold text-xl sm:text-3xl mt-10 justify-between border-t border-gray-300 dark:border-gray-700 pt-5'}>
                            <h4 className={'text-gray-900 dark:text-gray-100'}>
                                Total
                            </h4>
                            <h4 className={'text-gray-900 dark:text-gray-100'}>
                                {formatCurrency(data.totalPrice)}
                            </h4>
                        </div>
                    </div>
            }
        </section>
    );
}

export default DetailTransactionPage;

import BgHome from '../../assets/images/bgHome.webp';
import ImgCardHome from '../../assets/images/imgCardHome.png';
import DropDown from "../../component/ui/form/DropDown.tsx";
import {useEffect, useState} from "react";
import useTable from "../../hook/useTable.ts";
import useCartContext from "../../hook/useCartContext.ts";
import {useNavigate} from "react-router";
import useNotificationContext from "../../hook/useNotificationContext.ts";
import Cookie from "../../utils/cookie.ts";
import type {CartData} from "../../context/cart/CartContext.ts";

const HomePage = () => {

    const {getTableOptions, setOptions, options} = useTable()
    const cart = useCartContext()
    const navigate = useNavigate();
    const notification = useNotificationContext();
    const [selectedTable, setSelectedTable] = useState<{
        value: number;
        label: string;
    } | null>(null);
    const [loadingPage, setLoadingPage] = useState(true);

    useEffect(
        () => {
            const fetchData = async () => {
                try {
                    const res = await getTableOptions()
                    const cookieCart = Cookie.get('cart');
                    const data: CartData = cookieCart ? JSON.parse(cookieCart) : null;
                    if (res && data) {
                        const table = res.data.find((table) => table.id === data.tableId);
                        if (table) {
                            setSelectedTable({
                                value: table.id,
                                label: table.name
                            });
                            const optionsFiltered = res.data.filter((table) => table.id !== data.tableId).map((table) => ({
                                value: table.id,
                                label: table.name
                            }));
                            setOptions(optionsFiltered)
                        }
                    }
                } finally {
                    setLoadingPage(false);
                }
            }
            fetchData();
        }, []
    )

    const handleSelected = (value: { value: number; label: string } | null) => {
        setSelectedTable(value);
    }

    const handleSkip = () => {
        navigate('/menu');
    }

    const handleNext = () => {
        if (selectedTable) {
            cart.setTable({
                tableId: selectedTable.value,
                tableName: selectedTable.label,
            })
            navigate('/menu');
        } else {
            notification.warningNotificationClient('Please select a table')
        }
    }

    return (
        <section className={'bg-white dark:bg-gray-900 min-h-screen'}>
            <div className={'sm:h-[880px] h-[900px] relative'}>
                <img src={BgHome} alt="Coffee shop interior background" className="w-full h-full object-cover"/>
                <div className={'px-4'}>
                    <div
                        data-aos="fade-up" data-aos-duration={1000}
                        className={'bg-white md:w-2xl w-[calc(100%-2rem)] absolute p-8 sm:p-10 top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 rounded-2xl shadow-lg text-center dark:bg-gray-800 dark:shadow-none'}>
                        <div data-aos="fade-up">
                            <h2 className={'text-3xl mb-4 font-bold text-gray-900 dark:text-gray-100'}>
                                Welcome to Diskusi Coffee,
                            </h2>
                            <p className={'text-gray-700 dark:text-gray-300'}>
                                Choose your table
                            </p>
                            <div
                                className={'flex md:flex-row flex-col bg-[#F8F9F9] dark:bg-gray-700 gap-10 p-4 rounded-2xl'}>
                                <img src={ImgCardHome} alt='Table illustration' className={'mx-auto h-40'}/>
                                <div className={'text-start space-y-6'}>
                                    <p className={'text-gray-700 dark:text-gray-300'}>
                                        Every table has a story.
                                        Choose the one that fits you
                                        best.
                                    </p>
                                    {loadingPage ? (
                                        <div className="h-12 shimmer rounded-lg w-full"/>
                                    ) : (
                                        <DropDown
                                            name={'meja'}
                                            options={options}
                                            placeholder={'Select Table'}
                                            setValue={handleSelected}
                                            setOptions={setOptions}
                                            value={selectedTable}
                                        />
                                    )}
                                </div>
                            </div>
                            <div className={'flex items-center justify-center gap-4 mt-6'}>
                                <button onClick={handleSkip}
                                        className={'btn-primary-outline w-full px-10 py-3 rounded-xl'}>
                                    Skip
                                </button>
                                <button onClick={handleNext}
                                        className={'btn-primary w-full px-10 py-3 rounded-xl'}>
                                    Next
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </section>
    )
}

export default HomePage;

import BgMenu from '../../assets/images/bgMenu.png';
import DummyProduct from '../../assets/images/dummyProduct.png';
import {useEffect, useRef, useState} from "react";
import {HiMiniMagnifyingGlass} from "react-icons/hi2";
import DropDown from "../../component/ui/form/DropDown.tsx";
import useCategory from "../../hook/useCategory.ts";
import CardMenu from "../../component/ui/card/CardMenu.tsx";
import useMenu from "../../hook/useMenu.ts";
import CardMenuSkeleton from "../../component/ui/Skeleton/CardMenuSkeleton.tsx";

const MenuPage = () => {

    const {getCategoryOptions, setOptions, options} = useCategory()
    const {getMenu, page, handlePaginate, loading, data, totalData} = useMenu();
    const [loadingFirst, setLoadingFirst] = useState(true);
    const refLoader = useRef<HTMLDivElement>(null)
    const isMaxScroll = page * 12 >= totalData;
    const [filter, setFilter] = useState({
        showSearch: '',
        search: '',
        kategori: {
            value: 0,
            label: '',
        },
    })
    const [selectedTable, setSelectedTable] = useState<{
        value: number;
        label: string;
    } | null>(null);

    useEffect(
        () => {
            const fetchData = async () => {
                try {
                    await Promise.all([
                        getCategoryOptions(),
                        getMenu()
                    ])
                } finally {
                    setLoadingFirst(false);
                }
            }
            fetchData();
        }, []
    )

    useEffect(() => {
        const target = refLoader.current;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !loading && !isMaxScroll) {
                    handlePaginate(page + 1, {
                        category_id: filter.kategori.value,
                        search: filter.showSearch,
                    });
                }
            }, {
                threshold: 1
            }
        )

        if (target && !loading && !isMaxScroll) {
            observer.observe(target);
        }

        return () => {
            if (target) {
                observer.unobserve(target);
            }
        }

    }, [page, loading]);

    const handleSelected = async (value: { value: number; label: string } | null) => {
        if (value) {
            setSelectedTable(value);
            setFilter({
                ...filter,
                kategori: value,
            });
            setLoadingFirst(true);
            try {
                await handlePaginate(
                    1,
                    {
                        category_id: value.value,
                        search: filter.showSearch,
                    }
                )
            } finally {
                setLoadingFirst(false);
            }
        } else {
            setSelectedTable(null);
            setFilter({
                ...filter,
                kategori: {value: 0, label: ''},
            });
            setLoadingFirst(true);
            try {
                await handlePaginate(
                    1,
                    {
                        search: filter.showSearch,
                    }
                )
            } finally {
                setLoadingFirst(false);
            }
        }
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        setFilter({
            ...filter,
            search: e.target.value,
        });
    }

    const handleSearch = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setFilter({
            ...filter,
            showSearch: filter.search
        });
        setLoadingFirst(true);
        try {

            await handlePaginate(
                1,
                {
                    search: filter.search,
                }
            )
        } finally {

            setLoadingFirst(false);
        }
    }

    return (
        <section className={'relative flex items-center flex-col w-full bg-white dark:bg-gray-900'}>
            <img src={BgMenu} className={'h-[450px] sm:h-[550px] absolute w-full object-cover dark:opacity-60'} alt='Menu background'/>
            <div className={'absolute inset-x-0 mx-auto w-full my-20 sm:my-32 px-4'}>
                <h2 className={'sm:text-6xl text-3xl font-bold text-white text-center'}>Catalog Menu</h2>
                <p className={'text-white text-center mt-4 sm:text-2xl text-base max-w-2xl mx-auto'}>
                    Welcome to our Catalog Menu, where every dish is a carefully curated experience designed to delight
                    your senses.
                </p>
            </div>
            <div
                className={'bg-white dark:bg-gray-800 dark:border dark:border-gray-700 sm:p-10 p-5 rounded-2xl mb-10 z-10 w-[90%] mt-64 sm:mt-80'}>
                <h3 className={'font-bold text-3xl text-center mb-4 text-gray-900 dark:text-gray-100'}>
                    Discover Your Best Choices
                </h3>
                <form onSubmit={handleSearch}
                      className={'flex mx-auto items-center sm:w-1/2 justify-center border my-10 rounded-full bg-gray-100 dark:bg-gray-700'}>
                    <input
                        className={'px-4 focus:outline-none py-3 w-full bg-transparent text-gray-900 dark:text-gray-100 placeholder-gray-500 dark:placeholder-gray-300'}
                        onChange={handleChange}
                        placeholder={'Search menu...'}
                        value={filter.search}
                        aria-label="Search menu"
                    />
                    <button type="submit"
                            className={'btn-primary text-white p-2 rounded-full'}>
                        <HiMiniMagnifyingGlass className={'text-2xl sm:text-4xl'}/>
                    </button>
                </form>
                <div
                    className={'flex mx-auto items-center sm:flex-row flex-col gap-6 justify-between 2xl:w-2/3 xl:w-3/4 lg:w-full'}>
                    <p className={'text-gray-700 dark:text-gray-300'}>
                        {filter.showSearch ? `Result: ${filter.showSearch}` : 'All items'}
                    </p>
                    <div className={'w-56'}>
                        <DropDown
                            options={options}
                            setOptions={setOptions}
                            placeholder={'All Category'}
                            name={'category'}
                            value={selectedTable}
                            setValue={handleSelected}
                        />
                    </div>
                </div>
                <div
                    className={'lg:grid-cols-4 md:grid-cols-3 grid-cols-2 mt-10 sm:gap-10 gap-5 grid mx-auto items-center justify-between 2xl:w-2/3 xl:w-3/4 lg:w-full'}>
                    {
                        loadingFirst ?
                            Array.from({length: 12}, (_, index) => (
                                <CardMenuSkeleton
                                    key={index}
                                />
                            )) :
                            totalData === 0 && !loading ?
                                <div className="sm:p-20 col-span-full text-center py-16">
                                    <h3 className="text-xl font-semibold text-gray-800 dark:text-gray-100 mb-2">No menu
                                        found</h3>
                                    <p className="text-gray-500 dark:text-gray-400">Try a different search or category</p>
                                </div> :
                                data.map((menu, index) => (
                                    <CardMenu
                                        key={index}
                                        id={menu.id}
                                        photo={`${menu.photo || DummyProduct}`}
                                        name={menu.name}
                                        rating={menu.rating}
                                    />
                                ))
                    }
                    {
                        !isMaxScroll &&
                        <div ref={refLoader}
                             className={'flex col-span-full flex-col justify-center items-center w-full py-8'}
                        >
                            <div className="spinner mx-auto mb-4">
                            </div>
                            <p className={'text-gray-700 dark:text-gray-300'}>Load More ...</p>
                        </div>
                    }
                </div>
            </div>
        </section>
    )
}

export default MenuPage;

import {useEffect, useRef, useState} from "react";
import useOrder from "../../hook/useOrder.ts";
import CardTransactionSkeleton from "../../component/ui/Skeleton/CardTransactionSkeleton.tsx";
import CardTransaction from "../../component/ui/card/CardTransaction.tsx";

const TransactionPage = () => {

    const {getOrder, page, data, totalData, handlePaginate, loading} = useOrder();
    const refLoader = useRef<HTMLDivElement>(null);
    const isMaxScroll = page * 10 >= totalData;
    const [loadingFirst, setLoadingFirst] = useState(true);
    const [maxItems, setMaxItems] = useState(4)


    useEffect(() => {
        const target = refLoader.current;

        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !loading && !isMaxScroll) {
                    handlePaginate(page + 1, {search: ''});
                }
            }, {
                threshold: 1
            }
        )

        if (target && !loading && !isMaxScroll) {
            observer.observe(target);
        }

        return () => {
            if (target) {
                observer.unobserve(target);
            }
        }

    }, [page, loading]);

    useEffect(() => {
        const updateMaxItem = () => {
            const width = window.innerWidth
            if (width >= 1280) setMaxItems(4)       // xl ke atas
            else if (width >= 1024) setMaxItems(3)  // lg
            else if (width >= 768) setMaxItems(2)   // sm
            else setMaxItems(1)                     // sangat kecil
        }

        updateMaxItem()

        window.addEventListener('resize', updateMaxItem)
        return () => window.removeEventListener('resize', updateMaxItem)
    }, []);


    useEffect(() => {
        const fetchData = async () => {
            try {

                await getOrder()
            } finally {
                setLoadingFirst(false)
            }
        }
        fetchData()
    }, []);


    return (
        <section className="container mx-auto my-10 px-4">
            <div className={'flex gap-5'}>
                <h4 className={'text-gray-900 dark:text-gray-100'}>
                    Menu
                </h4>
                <span className={'text-gray-600 dark:text-gray-400'}>
                    /
                </span>
                <h4 className={'font-bold text-gray-900 dark:text-gray-100'}>
                    Transactions
                </h4>
            </div>
            <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl flex justify-between items-center'}>
                <h4 className={'font-bold text-3xl sm:text-5xl text-gray-900 dark:text-gray-100'}>
                    Transactions
                </h4>
            </div>
            {
                loadingFirst ?
                    Array.from({length: 10}).map((_, index) => (
                            <CardTransactionSkeleton maxItems={maxItems} key={index}/>
                        )
                    ) :
                    totalData === 0 ?
                        <div className={'mt-10 bg-white dark:bg-gray-800 p-8 rounded-2xl text-center'}>
                            <h4 className={'text-xl font-bold text-gray-900 dark:text-gray-100'}>
                                No Transactions Found
                            </h4>
                        </div> :
                        data.map((transaction, index) => (
                            <CardTransaction maxItems={maxItems} key={index} {...transaction}/>
                        ))
            }
            {
                !isMaxScroll &&
                <div ref={refLoader} className={'flex mt-10 flex-col justify-center items-center w-full'}>
                    <div className="spinner mx-auto mb-4"/>
                    <p className={'text-gray-700 dark:text-gray-300'}>Load More ...</p>
                </div>
            }
        </section>
    );
}

export default TransactionPage;

import useWallet from "../../hook/useWallet.ts";
import WalletSkeleton from "../../component/ui/Skeleton/WalletSkeleton.tsx";
import {useEffect, useState} from "react";
import WalletNotActive from "../../component/WalletNotActive.tsx";
import WalletActive from "../../component/WalletActive.tsx";
import type {Wallet} from "../../model/wallet.ts";
import PageHeader from "../../component/PageHeader.tsx";

const WalletPage = () => {

    const {checkWallet, loading, handleTopUp} = useWallet()

    const [data, setData] = useState<Wallet>({
        balance: 0,
        isActive: false
    });

    useEffect(() => {
        const fetchWallet = async () => {
            const res = await checkWallet();
            if (res && res.data) {
                setData({
                    isActive: res.data.isActive,
                    balance: res.data.balance
                })
            } else {
                setData({
                    isActive: false,
                    balance: 0
                })
            }
        };
        fetchWallet();
    }, []);

    return (
        <section className="container mx-auto my-10 px-4">
            <PageHeader
                breadcrumb={[{label: 'Menu', to: '/menu'}, {label: 'Wallet'}]}
                title="Wallet"
            />
            {
                loading ? <WalletSkeleton/> :
                    data.isActive ?
                        <WalletActive balance={data.balance} setBalance={setData} handleTopUp={handleTopUp}/>
                        :
                        <WalletNotActive/>
            }
        </section>
    );
}

export default WalletPage;
